/**
 * Chronosense golden parity suite: pins packages/caelus/src/chronosense.ts
 * (chronosenseEnvelope, auditChronosenseCursor, photoperiodVector,
 * phaseStratumKey, phaseCosineSimilarity, stratifiedSelect) against every
 * case in chronosense-golden.json generated by python/export_chronosense_golden.py.
 *
 * Both implementations run on identical embedded VSOP + full Moon data, so
 * digests, headers, flags, strata, and selection IDs match exactly (===) and
 * floats match within <= 1e-6.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { Engine } from "../src/chart.js";
import { loadNodeData } from "../src/node-loader.js";
import { sceneGeometry } from "../src/observe.js";
import {
  chronosenseEnvelope,
  auditChronosenseCursor,
  photoperiodVector,
  phaseStratumKey,
  phaseCosineSimilarity,
  stratifiedSelect,
  type ChronosenseEnvelope,
  type ChronosenseEnvelopeOptions,
  type ChronosenseCursor,
  type ChronosenseAuditOptions,
  type ChronosenseAuditResult,
} from "../src/chronosense.js";

const here = dirname(fileURLToPath(import.meta.url));
const G = JSON.parse(readFileSync(join(here, "../../test/chronosense-golden.json"), "utf8"));
const eng = new Engine(loadNodeData(join(here, "../../data"), "embedded", "full"));

// -------------------------------------------------- snake_case <-> camelCase

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function toEnvelopeOpts(raw: any): ChronosenseEnvelopeOptions {
  if (!raw) return {};
  return {
    turn: raw.turn,
    prevJdUt: raw.prev_jd_ut,
    deadlineJdUt: raw.deadline_jd_ut,
    deadlineLabel: raw.deadline_label,
    elevationM: raw.elevation_m,
    genesisDigest: raw.genesis_digest,
  };
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function toCursorCamel(raw: any): ChronosenseCursor {
  if (!raw || typeof raw !== "object") return raw;
  const out: ChronosenseCursor = {};
  if ("clock_id" in raw) out.clockId = raw.clock_id;
  if ("turn" in raw) out.turn = raw.turn;
  if ("night_crossed_ack" in raw) out.nightCrossedAck = raw.night_crossed_ack;
  if ("deadline_eta_min" in raw) out.deadlineEtaMin = raw.deadline_eta_min;
  if ("cited_facts" in raw) out.citedFacts = raw.cited_facts;
  return out;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function toAuditOpts(raw: any): ChronosenseAuditOptions {
  if (!raw) return {};
  return {
    deadlineToleranceMin: raw.deadline_tolerance_min,
    factTolerance: raw.fact_tolerance,
  };
}

function mapEnvelope(e: ChronosenseEnvelope): Record<string, unknown> {
  return {
    clock_id: e.clockId,
    chart_digest: e.chartDigest,
    genesis_digest: e.genesisDigest,
    turn: e.turn,
    jd_ut: e.jdUt,
    utc_iso: e.utcIso,
    lat: e.lat,
    lon_east: e.lonEast,
    elevation_m: e.elevationM,
    sun_alt_deg: e.sunAltDeg,
    sun_trend: e.sunTrend,
    twilight: e.twilight,
    day_slot: e.daySlot,
    is_day: e.isDay,
    night_crossed: e.nightCrossed,
    horizon_event: e.horizonEvent,
    horizon_eta_min: e.horizonEtaMin,
    deadline_label: e.deadlineLabel,
    deadline_eta_min: e.deadlineEtaMin,
    deadline_state: e.deadlineState,
    moon_lon_deg: e.moonLonDeg,
    moon_illum_pct: e.moonIllumPct,
    moon_waxing: e.moonWaxing,
    dt_prev_min: e.dtPrevMin,
    wavefront_quadrant: e.wavefrontQuadrant,
    header: e.header,
  };
}

function mapAudit(r: ChronosenseAuditResult): Record<string, unknown> {
  return {
    ok: r.ok,
    drift_flags: r.driftFlags,
    corrective_prompt: r.correctivePrompt,
  };
}

// ------------------------------------------------------------------ comparison

let checks = 0;
let failures = 0;
let worst = 0;
let worstPath = "";
const TOL = 1e-6;

const CYCLIC_360_KEYS = new Set(["moon_lon_deg"]);
const EXACT_INT_KEYS = new Set(["turn", "day_slot"]);

function cyclicDiff360(a: number, b: number): number {
  const r = ((((a - b) + 180.0) % 360.0) + 360.0) % 360.0 - 180.0;
  return Math.abs(r);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function leaf(id: string, got: any, want: any, key?: string): void {
  checks++;
  if (typeof want === "number") {
    if (key && EXACT_INT_KEYS.has(key)) {
      if (got !== want) {
        failures++;
        console.error(`FAIL ${id}: ${got} vs ${want}`);
      }
      return;
    }
    const d = (key && CYCLIC_360_KEYS.has(key))
      ? cyclicDiff360(got, want)
      : Math.abs(got - want);
    if (d > worst) {
      worst = d;
      worstPath = id;
    }
    if (typeof got !== "number" || !Number.isFinite(got) || d > TOL) {
      failures++;
      console.error(`FAIL ${id}: ${got} vs ${want} (diff ${d})`);
    }
  } else if (got !== want) {
    failures++;
    console.error(`FAIL ${id}: ${JSON.stringify(got)} vs ${JSON.stringify(want)}`);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function deepCmp(id: string, got: any, want: any, key?: string): void {
  if (Array.isArray(want)) {
    if (!Array.isArray(got) || got.length !== want.length) {
      checks++;
      failures++;
      console.error(`FAIL ${id}: array length ${got?.length} vs ${want.length}`);
      return;
    }
    for (let i = 0; i < want.length; i++) {
      deepCmp(`${id}[${i}]`, got[i], want[i]);
    }
  } else if (want !== null && typeof want === "object") {
    if (got === null || typeof got !== "object") {
      checks++;
      failures++;
      console.error(`FAIL ${id}: got ${JSON.stringify(got)}, want object`);
      return;
    }
    for (const k of Object.keys(want)) {
      deepCmp(`${id}.${k}`, got[k], want[k], k);
    }
  } else {
    leaf(id, got, want, key);
  }
}

// ------------------------------------------------------------------ run cases

const envelopes = new Map<string, ChronosenseEnvelope>();

// eslint-disable-next-line @typescript-eslint/no-explicit-any
for (const c of G.cases as any[]) {
  const s = c.spec;
  switch (c.type) {
    case "envelope": {
      const env = chronosenseEnvelope(eng, s.jd_ut, s.lat, s.lon_east, toEnvelopeOpts(s.options));
      envelopes.set(c.id, env);
      deepCmp(c.id, mapEnvelope(env), c.result);
      break;
    }
    case "audit": {
      const env = envelopes.get(s.envelope_id);
      if (!env) throw new Error(`missing envelope ${s.envelope_id} for ${c.id}`);
      const opts = toAuditOpts(s.options);
      const resCamel = auditChronosenseCursor(env, toCursorCamel(s.cursor), opts);
      deepCmp(`${c.id}[camel]`, mapAudit(resCamel), c.result);
      // Also verify snake_case wire JSON directly matches identical output.
      const resSnake = auditChronosenseCursor(env, s.cursor, opts);
      deepCmp(`${c.id}[snake]`, mapAudit(resSnake), c.result);
      break;
    }
    case "phase": {
      const scA = sceneGeometry(eng, s.a.jd_ut, s.a.lat, s.a.lon_east);
      const scB = sceneGeometry(eng, s.b.jd_ut, s.b.lat, s.b.lon_east);
      const vecA = photoperiodVector(scA);
      const vecB = photoperiodVector(scB);
      const stratumA = phaseStratumKey(scA, s.a.lon_east);
      const stratumB = phaseStratumKey(scB, s.b.lon_east);
      const cosSim = phaseCosineSimilarity(vecA, vecB);
      deepCmp(c.id, {
        vector_a: vecA,
        vector_b: vecB,
        stratum_a: stratumA,
        stratum_b: stratumB,
        cosine_similarity: cosSim,
      }, c.result);
      break;
    }
    case "stratified_select": {
      const picked = stratifiedSelect(s.entries, s.budget);
      deepCmp(c.id, picked, c.result);
      break;
    }
    default:
      throw new Error(`unknown golden case type ${c.type}`);
  }
}

console.log(`chronosense-golden: ${G.cases.length} cases, ${checks} checks, ${failures} failures`);
console.log(`worst numeric diff: ${worst.toExponential(2)} (${worstPath})`);
process.exit(failures === 0 ? 0 : 1);
